declare
  v_norm    text;
  v_blocked integer := 0;
  v_removed integer := 0;
begin
  if not is_owner() then
    raise exception 'only the owner may action an erasure request';
  end if;

  -- Must match normalisePhone() in src/lib/idempotency.ts and lookup_order().
  v_norm := regexp_replace(p_phone, '\D', '', 'g');
  if left(v_norm, 2) = '63' then v_norm := '0' || substr(v_norm, 3); end if;

  -- Live orders: nothing to preserve, remove them.
  with removed as (
    delete from orders
    where regexp_replace(phone, '\D', '', 'g') = v_norm
      -- 'Payment review' is where an order sits before proof of payment arrives. Nothing
      -- has been paid and no tax record exists, so there is nothing to preserve.
      and state = 'Payment review'
      and pay_state = 'unpaid'
    returning 1
  )
  select count(*) into v_removed from removed;

  -- Everything else is a financial record. Block, do not erase.
  with blocked as (
    update orders
       set customer_name = 'Removed on request',
           phone = '',
           notes = ''
     where regexp_replace(phone, '\D', '', 'g') = v_norm
    returning 1
  )
  select count(*) into v_blocked from blocked;

  insert into erasure_requests (phone_hash, actioned_at, action, note, orders_affected)
  values (encode(digest(v_norm, 'sha256'), 'hex'), now(), 'anonymised', p_note, v_blocked + v_removed);

  return v_blocked + v_removed;
end;

select p_requested > 0
   and p_requested <= greatest(0, greatest(0, floor(p_capacity)::integer)
                                  - greatest(0, floor(p_committed)::integer));

declare
  v_start timestamptz;
  v_count integer;
begin
  if p_limit <= 0 or p_window_s <= 0 then
    raise exception 'consume_rate_limit: limit and window must be positive';
  end if;

  -- Truncate now() to the window, so every caller in the same window agrees on the key.
  v_start := to_timestamp(floor(extract(epoch from now()) / p_window_s) * p_window_s);

  insert into rate_limits (key, window_start, count)
  values (p_key, v_start, 1)
  on conflict (key, window_start)
    do update set count = rate_limits.count + 1
  returning rate_limits.count into v_count;

  return query select
    v_count <= p_limit,
    greatest(p_limit - v_count, 0),
    v_start + make_interval(secs => p_window_s);
end;

declare
  v_count integer;
begin
  with pruned as (
    update orders
       set customer_name = 'Past customer',
           phone = '',
           notes = ''
     where placed_at < now() - make_interval(days => p_retain_days)
       and phone <> ''
    returning 1
  )
  select count(*) into v_count from pruned;
  return v_count;
end;

declare
  v_deleted integer;
begin
  delete from rate_limits where window_start < now() - interval '2 hours';
  get diagnostics v_deleted = row_count;
  return v_deleted;
end;

begin
  new.updated_at := now();
  new.updated_by := auth.uid();
  return new;
end;

declare
  v_client_id text := p_sale ->> 'clientId';
  v_existing  uuid;
  v_sale_id   uuid;
  v_ledger_id uuid;
  v_item      jsonb;
begin
  if not is_staff() then
    raise exception 'not authorised' using errcode = '42501';
  end if;
  if v_client_id is null or length(v_client_id) = 0 then
    raise exception 'clientId is required' using errcode = '22023';
  end if;

  select es.id into v_existing from event_sales es where es.client_id = v_client_id;
  if v_existing is not null then
    return query select v_client_id, v_existing, true;
    return;
  end if;

  insert into ledger_entries (kind, category, memo, amount_cents, occurred_at, created_by)
  values (
    'sale', 'Bazaar', 'Stall sale ' || v_client_id,
    (p_sale ->> 'total')::numeric * 100,
    to_timestamp((p_sale ->> 'at')::bigint / 1000.0),
    auth.uid()
  )
  returning id into v_ledger_id;

  insert into event_sales (
    client_id, event_id, gross_cents, discount_cents, total_cents,
    pay_method, pay_ref, tendered_cents, change_cents, clerk, sold_at, ledger_id
  ) values (
    v_client_id,
    nullif(p_sale ->> 'eventId', '')::uuid,
    (p_sale ->> 'gross')::numeric * 100,
    coalesce((p_sale ->> 'discount')::numeric, 0) * 100,
    (p_sale ->> 'total')::numeric * 100,
    coalesce(p_sale ->> 'pay', 'cash'),
    coalesce(p_sale ->> 'ref', ''),
    coalesce((p_sale ->> 'tendered')::numeric, 0) * 100,
    coalesce((p_sale ->> 'change')::numeric, 0) * 100,
    coalesce(p_sale ->> 'clerk', ''),
    to_timestamp((p_sale ->> 'at')::bigint / 1000.0),
    v_ledger_id
  )
  returning id into v_sale_id;

  for v_item in select * from jsonb_each(coalesce(p_sale -> 'items', '{}'::jsonb))
  loop
    insert into event_sale_items (sale_id, product_id, qty, unit_price_cents)
    select v_sale_id, p.id, (v_item -> 1)::text::int, p.price_cents
    from products p where p.id = (v_item -> 0)::text;
  end loop;

  insert into audit_log (actor, action, entity, entity_id, detail)
  values (auth.uid(), 'sale.synced', 'event_sales', v_sale_id::text, p_sale);

  return query select v_client_id, v_sale_id, false;
end

begin
  new.updated_at := now();
  return new;
end;

